INSERT INTO posts VALUES('75a055e0-aec1-4d46-9ff6-cccc3f2a93fe','workspace-local','Glassmorphic Landing','glassmorphic-landing',NULL,'published','page','html',replace('<style>\n.gm-landing {\n  --gm-accent: var(--accent, #8a4b2a);\n  --gm-fg: var(--fg, #1b1613);\n  --gm-muted: var(--muted, #6b625c);\n  --gm-glass: rgba(255, 255, 255, 0.42);\n  --gm-glass-edge: rgba(255, 255, 255, 0.65);\n  --gm-shadow: 0 18px 50px -20px rgba(20, 14, 10, 0.45);\n  --gm-radius: var(--radius, 20px);\n  position: relative;\n  isolation: isolate;\n  overflow: hidden;\n  color: var(--gm-fg);\n  border-radius: var(--gm-radius);\n  padding: 1px;\n}\n.gm-landing::before,\n.gm-landing::after {\n  content: "";\n  position: absolute;\n  z-index: -1;\n  border-radius: 50%;\n  filter: blur(70px);\n  opacity: 0.55;\n  pointer-events: none;\n}\n.gm-landing::before {\n  width: 46rem; height: 46rem;\n  top: -18rem; left: -12rem;\n  background: radial-gradient(circle at 30% 30%, var(--gm-accent), transparent 68%);\n}\n.gm-landing::after {\n  width: 40rem; height: 40rem;\n  bottom: -20rem; right: -14rem;\n  background: radial-gradient(circle at 60% 40%, var(--accent-2, #2a6b8a), transparent 68%);\n}\n.gm-landing * { box-sizing: border-box; }\n\n.gm-glass {\n  background: var(--gm-glass);\n  border: 1px solid var(--gm-glass-edge);\n  border-radius: var(--gm-radius);\n  box-shadow: var(--gm-shadow);\n  -webkit-backdrop-filter: blur(18px) saturate(150%);\n  backdrop-filter: blur(18px) saturate(150%);\n}\n\n.gm-hero {\n  display: flex;\n  flex-direction: column;\n  align-items: center;\n  text-align: center;\n  gap: 1.25rem;\n  padding: clamp(2.5rem, 7vw, 5rem) clamp(1.25rem, 5vw, 3.5rem);\n  margin: clamp(1rem, 3vw, 2rem) 0;\n}\n.gm-pill {\n  display: inline-flex;\n  align-items: center;\n  gap: 0.5rem;\n  padding: 0.4rem 0.9rem;\n  font-size: 0.78rem;\n  letter-spacing: 0.09em;\n  text-transform: uppercase;\n  color: var(--gm-accent);\n  background: rgba(255, 255, 255, 0.5);\n  border: 1px solid var(--gm-glass-edge);\n  border-radius: 999px;\n}\n.gm-pill svg { display: block; }\n.gm-hero h1 {\n  margin: 0;\n  font-size: clamp(2.1rem, 6vw, 3.9rem);\n  line-height: 1.05;\n  letter-spacing: -0.03em;\n  max-width: 18ch;\n}\n.gm-hero p {\n  margin: 0;\n  max-width: 52ch;\n  font-size: clamp(1rem, 1.6vw, 1.18rem);\n  line-height: 1.65;\n  color: var(--gm-muted);\n}\n.gm-actions {\n  display: flex;\n  flex-wrap: wrap;\n  justify-content: center;\n  gap: 0.75rem;\n  margin-top: 0.5rem;\n}\n.gm-btn {\n  display: inline-block;\n  padding: 0.8rem 1.6rem;\n  border-radius: 999px;\n  font-weight: 600;\n  text-decoration: none;\n  transition: transform 0.18s ease, box-shadow 0.18s ease;\n}\n.gm-btn:hover { transform: translateY(-2px); }\n.gm-btn--solid {\n  color: var(--on-accent, #fff);\n  background: var(--gm-accent);\n  box-shadow: 0 10px 26px -10px var(--gm-accent);\n}\n.gm-btn--ghost {\n  color: var(--gm-fg);\n  background: rgba(255, 255, 255, 0.45);\n  border: 1px solid var(--gm-glass-edge);\n  -webkit-backdrop-filter: blur(12px);\n  backdrop-filter: blur(12px);\n}\n\n.gm-grid {\n  display: grid;\n  grid-template-columns: repeat(auto-fit, minmax(15rem, 1fr));\n  gap: clamp(0.9rem, 2vw, 1.4rem);\n  margin: clamp(1rem, 3vw, 2rem) 0;\n}\n.gm-card {\n  padding: 1.6rem 1.5rem;\n  display: flex;\n  flex-direction: column;\n  gap: 0.6rem;\n}\n.gm-card h3 {\n  margin: 0;\n  font-size: 1.08rem;\n  letter-spacing: -0.01em;\n}\n.gm-card p {\n  margin: 0;\n  font-size: 0.95rem;\n  line-height: 1.6;\n  color: var(--gm-muted);\n}\n.gm-icon {\n  width: 2.5rem;\n  height: 2.5rem;\n  display: grid;\n  place-items: center;\n  border-radius: 14px;\n  color: var(--gm-accent);\n  background: rgba(255, 255, 255, 0.55);\n  border: 1px solid var(--gm-glass-edge);\n}\n\n.gm-stats {\n  display: grid;\n  grid-template-columns: repeat(auto-fit, minmax(9rem, 1fr));\n  gap: 1px;\n  overflow: hidden;\n  margin: clamp(1rem, 3vw, 2rem) 0;\n}\n.gm-stat {\n  padding: 1.4rem 1.2rem;\n  text-align: center;\n  background: rgba(255, 255, 255, 0.18);\n}\n.gm-stat b {\n  display: block;\n  font-size: clamp(1.6rem, 3.4vw, 2.3rem);\n  letter-spacing: -0.03em;\n  color: var(--gm-accent);\n}\n.gm-stat span {\n  font-size: 0.82rem;\n  letter-spacing: 0.06em;\n  text-transform: uppercase;\n  color: var(--gm-muted);\n}\n\n.gm-cta {\n  text-align: center;\n  padding: clamp(2rem, 5vw, 3.5rem) clamp(1.25rem, 5vw, 3rem);\n  margin: clamp(1rem, 3vw, 2rem) 0;\n}\n.gm-cta h2 {\n  margin: 0 0 0.6rem;\n  font-size: clamp(1.5rem, 3.6vw, 2.3rem);\n  letter-spacing: -0.02em;\n}\n.gm-cta p {\n  margin: 0 auto 1.4rem;\n  max-width: 46ch;\n  color: var(--gm-muted);\n  line-height: 1.65;\n}\n\n@media (prefers-color-scheme: dark) {\n  .gm-landing {\n    --gm-glass: rgba(255, 255, 255, 0.08);\n    --gm-glass-edge: rgba(255, 255, 255, 0.16);\n    --gm-fg: var(--fg, #f2ede9);\n    --gm-muted: var(--muted, #a9a09a);\n    --gm-shadow: 0 18px 50px -20px rgba(0, 0, 0, 0.7);\n  }\n  .gm-pill,\n  .gm-icon,\n  .gm-btn--ghost { background: rgba(255, 255, 255, 0.08); }\n  .gm-stat { background: rgba(255, 255, 255, 0.05); }\n}\n\n@media (prefers-reduced-motion: reduce) {\n  .gm-btn { transition: none; }\n  .gm-btn:hover { transform: none; }\n}\n</style>\n\n<div class="gm-landing">\n\n  <section class="gm-glass gm-hero" data-agent-element="page-hero" data-agent-role="region">\n    <span class="gm-pill">\n      <svg width="12" height="12" viewBox="0 0 12 12" aria-hidden="true" focusable="false"><circle cx="6" cy="6" r="4" fill="currentColor"/></svg>\n      Now in open beta\n    </span>\n    <h1>Everything you''ll need, behind one pane of glass.</h1>\n    <p>A calmer way to run your work. Clear surfaces, honest defaults, and nothing between you and the thing you came here to do.</p>\n    <div class="gm-actions">\n      <a class="gm-btn gm-btn--solid" href="#get-started">Get started</a>\n      <a class="gm-btn gm-btn--ghost" href="#features">See how it works</a>\n    </div>\n  </section>\n\n  <section id="features" class="gm-grid" data-agent-element="page-body" data-agent-role="region">\n    <article class="gm-glass gm-card">\n      <span class="gm-icon" aria-hidden="true">\n        <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"><path d="M13 2 3 14h8l-1 8 10-12h-8z"/></svg>\n      </span>\n      <h3>Fast by default</h3>\n      <p>Pages render in a blink, because nothing loads that you did not ask for. No trackers, no blocking scripts, no waiting.</p>\n    </article>\n\n    <article class="gm-glass gm-card">\n      <span class="gm-icon" aria-hidden="true">\n        <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"><rect x="4" y="10" width="16" height="11" rx="2"/><path d="M8 10V7a4 4 0 0 1 8 0v3"/></svg>\n      </span>\n      <h3>Private by design</h3>\n      <p>Your content stays yours. Everything is stored on your own site, and every change is written to an audit trail you can read.</p>\n    </article>\n\n    <article class="gm-glass gm-card">\n      <span class="gm-icon" aria-hidden="true">\n        <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"><path d="M12 3v18M3 12h18"/><circle cx="12" cy="12" r="9"/></svg>\n      </span>\n      <h3>Built to extend</h3>\n      <p>Start with the essentials and add only what earns its place. Every piece is optional, and nothing breaks when you remove it.</p>\n    </article>\n  </section>\n\n  <section class="gm-glass gm-stats" data-agent-element="page-stats" data-agent-role="region">\n    <div class="gm-stat"><b>99.9%</b><span>Uptime</span></div>\n    <div class="gm-stat"><b>&lt;100ms</b><span>Median load</span></div>\n    <div class="gm-stat"><b>0</b><span>Trackers</span></div>\n    <div class="gm-stat"><b>24/7</b><span>Support</span></div>\n  </section>\n\n  <section id="get-started" class="gm-glass gm-cta" data-agent-element="page-cta" data-agent-role="region">\n    <h2>Ready when you are.</h2>\n    <p>Set it up in an afternoon, keep it for years. No contracts, no migration tax, no surprises at renewal.</p>\n    <a class="gm-btn gm-btn--solid" href="#get-started">Start free</a>\n  </section>\n\n\n  <section class="gm-glass gm-cta" data-agent-element="page-contact" data-agent-role="region">\n    <h2>Get in touch</h2>\n    <p>Questions before you start? Send us a note.</p>\n    <div data-embed-config=''{"type":"widget","id":"29721c44-a811-444f-b7b5-e61a9918a3a9"}''></div>\n  </section>\n</div>','\n',char(10)),'2026-08-08T04:44:23.509Z',11,NULL,'{}',NULL,NULL,0);
